if mibBuilder.loadTexts: coIfXcvrForwardLaserControl.setStatus('current')
if mibBuilder.loadTexts: coIfXcvrForwardLaserControl.setDescription('This object is used to enable or disable Forward Laser Control\n        (FLC) on this interface.  If Forward Laser Control is enabled,\n        the laser is automatically shut down when the receive direction\n        of the cross-connected interface is in an alarm condition.')
coIfXcvrLaserSafetyControl = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 10, 66, 1, 4, 1, 1, 7), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("enable", 1), ("disable", 2)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: coIfXcvrLaserSafetyControl.setStatus('current')
if mibBuilder.loadTexts: coIfXcvrLaserSafetyControl.setDescription('This object is used to enable or disable Laser Safety Control\n        (LSC) mechanisms such as Automatic Laser Shutdown (ALS) on this\n        interface.  Laser Safety Control mechanisms are used to\n        automatically shutdown the output power of laser transmitters\n        when potentially hazardous conditions such as fiber breaks or\n        unplugged optical connectors are detected.')
coIfXcvrLSCProtocol = MibTableColumn((1, 3, 6, 1, 4, 1, 9, 10, 66, 1, 4, 1, 1, 8), Integer32().subtype(subtypeSpec=ConstraintsUnion(SingleValueConstraint(1, 2))).clone(namedValues=NamedValues(("proprietary", 1), ("g664", 2)))).setMaxAccess("readwrite")
if mibBuilder.loadTexts: coIfXcvrLSCProtocol.setReference('ITU-T Recommendation G.664, Optical safety procedures and\n        requirements for optical transport systems, June 1999')
